from __future__ import annotations

import logging
from collections.abc import Callable
from typing import Any, Literal

import litellm
from django.conf import settings
from django.core.exceptions import ImproperlyConfigured
from openai import OpenAI

logger = logging.getLogger(__name__)

Workload = Literal[
    "text_fast",
    "text_bulk",
    "reasoning",
    "vision",
    "vision_high_accuracy",
    "transcription",
]

_WORKLOAD_MODEL_SETTINGS: dict[Workload, str] = {
    "text_fast": "AI_TEXT_FAST_MODEL",
    "text_bulk": "AI_TEXT_BULK_MODEL",
    "reasoning": "AI_REASONING_MODEL",
    "vision": "AI_VISION_MODEL",
    "vision_high_accuracy": "AI_VISION_HIGH_ACCURACY_MODEL",
    "transcription": "AI_TRANSCRIPTION_MODEL",
}

_MODEL_PREFIX_TO_PROVIDER = {
    "claude": "anthropic",
    "gemini": "gemini",
}

_OPENAI_MODEL_PREFIXES = ("gpt-", "o1", "o3", "o4", "whisper-")
_PROVIDER_API_KEY_SETTINGS = {
    "anthropic": "ANTHROPIC_API_KEY",
    "gemini": "GEMINI_API_KEY",
    "openai": "OPENAI_API_KEY",
    "openrouter": "OPENROUTER_API_KEY",
}


def _infer_provider(model_name: str) -> str:
    normalized_model_name = model_name.strip().lower()
    for prefix, provider in _MODEL_PREFIX_TO_PROVIDER.items():
        if normalized_model_name.startswith(prefix):
            return provider
    if normalized_model_name.startswith(_OPENAI_MODEL_PREFIXES):
        return "openai"
    logger.error(
        "Cannot infer provider for model %r; use explicit '<provider>/<model>' form.",
        model_name,
    )
    raise ValueError(
        f"Cannot infer provider for model {model_name!r}; "
        "use explicit '<provider>/<model>' form."
    )


def normalize_model_name(model: str) -> str:
    normalized_model = model.strip()
    if not normalized_model:
        raise ValueError("Model name is required")

    provider: str
    model_name: str
    for separator in (":", "/"):
        if separator in normalized_model:
            provider, model_name = normalized_model.split(separator, 1)
            break
    else:
        provider = _infer_provider(normalized_model)
        model_name = normalized_model

    provider = provider.strip().lower()
    model_name = model_name.strip()
    if not provider or not model_name:
        raise ValueError(f"Invalid model identifier: {model!r}")
    return f"{provider}/{model_name}"


def get_workload_model(workload: Workload) -> str:
    setting_name = _WORKLOAD_MODEL_SETTINGS.get(workload)
    if setting_name is None:
        raise ValueError(f"Unknown AI workload: {workload}")

    configured_model = str(getattr(settings, setting_name, "")).strip()
    if not configured_model:
        raise ImproperlyConfigured(f"{setting_name} is not configured.")
    return normalize_model_name(configured_model)


def _normalize_openai_model_name(model: str) -> str:
    normalized_model = normalize_model_name(model)
    provider, model_name = normalized_model.split("/", 1)
    if provider != "openai":
        raise ValueError(f"Unsupported audio transcription provider: {provider}")
    return model_name


def _resolve_provider_api_key(
    provider: str, *, override: str | None = None
) -> str | None:
    if override:
        return override
    setting_name = _PROVIDER_API_KEY_SETTINGS.get(provider)
    if setting_name is None:
        return None
    value = str(getattr(settings, setting_name, "")).strip()
    return value or None


def _resolve_proxy_config() -> tuple[str | None, str | None]:
    """Return (api_base, api_key) if LiteLLM proxy is configured, else (None, None)."""
    proxy_base_url = str(getattr(settings, "LITELLM_PROXY_BASE_URL", "") or "").strip()
    if not proxy_base_url:
        return None, None
    proxy_api_key = str(getattr(settings, "LITELLM_PROXY_API_KEY", "") or "").strip()
    return proxy_base_url, proxy_api_key or None


class _ChatCompletionsClient:
    def __init__(
        self,
        *,
        api_key: str | None = None,
        openai_proxy_client_factory: Callable[[str | None, str], OpenAI],
    ) -> None:
        self._api_key = api_key
        self._openai_proxy_client_factory = openai_proxy_client_factory

    def create(self, *, model: str, **kwargs: Any) -> Any:
        resolved_model = normalize_model_name(model)
        request_kwargs = dict(kwargs)

        proxy_base_url, proxy_api_key = _resolve_proxy_config()
        if proxy_base_url:
            # Route through the LiteLLM proxy with the OpenAI SDK so the
            # request stays on /chat/completions instead of provider-native
            # endpoints like /models/...:generateContent.
            effective_key = self._api_key or proxy_api_key
            proxy_client = self._openai_proxy_client_factory(
                effective_key, proxy_base_url
            )
            return proxy_client.chat.completions.create(
                model=resolved_model,
                **request_kwargs,
            )
        else:
            provider, _ = resolved_model.split("/", 1)
            provider_api_key = _resolve_provider_api_key(
                provider, override=self._api_key
            )
            if provider_api_key and "api_key" not in request_kwargs:
                request_kwargs["api_key"] = provider_api_key

        logger.debug(
            "AI completion request requested_model=%s resolved_model=%s proxy=%s",
            model,
            resolved_model,
            bool(proxy_base_url),
        )
        return litellm.completion(model=resolved_model, **request_kwargs)


class _ChatClient:
    def __init__(
        self,
        *,
        api_key: str | None = None,
        openai_proxy_client_factory: Callable[[str | None, str], OpenAI],
    ) -> None:
        self.completions = _ChatCompletionsClient(
            api_key=api_key,
            openai_proxy_client_factory=openai_proxy_client_factory,
        )


class _AudioTranscriptionsClient:
    def __init__(self, openai_client_factory: Callable[[], OpenAI]) -> None:
        self._openai_client_factory = openai_client_factory

    def create(self, *, model: str, **kwargs: Any) -> Any:
        resolved_model = _normalize_openai_model_name(model)
        logger.debug(
            "AI transcription request requested_model=%s resolved_model=openai/%s",
            model,
            resolved_model,
        )
        return self._openai_client_factory().audio.transcriptions.create(
            model=resolved_model,
            **kwargs,
        )


class _AudioClient:
    def __init__(self, openai_client_factory: Callable[[], OpenAI]) -> None:
        self.transcriptions = _AudioTranscriptionsClient(openai_client_factory)


class AIClient:
    def __init__(
        self, api_key: str | None = None, audio_api_key: str | None = None
    ) -> None:
        self._completion_api_key = api_key
        self._audio_api_key = audio_api_key or _resolve_provider_api_key(
            "openai",
            override=api_key,
        )
        self._openai_audio_client: OpenAI | None = None
        self._openai_proxy_clients: dict[tuple[str | None, str], OpenAI] = {}
        self.chat = _ChatClient(
            api_key=self._completion_api_key,
            openai_proxy_client_factory=self._get_openai_proxy_client,
        )
        self.audio = _AudioClient(self._get_openai_audio_client)

    def _get_openai_audio_client(self) -> OpenAI:
        if self._openai_audio_client is None:
            self._openai_audio_client = OpenAI(api_key=self._audio_api_key)
        return self._openai_audio_client

    def _get_openai_proxy_client(self, api_key: str | None, base_url: str) -> OpenAI:
        cache_key = (api_key, base_url)
        client = self._openai_proxy_clients.get(cache_key)
        if client is None:
            client = OpenAI(api_key=api_key or "sk-litellm-proxy", base_url=base_url)
            self._openai_proxy_clients[cache_key] = client
        return client

