    def read_current_family_calendar_events(
        self, family: FamilyGroup, *, limit: int = 25
    ) -> list[dict[str, Any]]:
        now = timezone.now()
        events = (
            Event.objects.filter(
                family_group=family,
                start_time__gte=now,
            )
            .order_by("start_time")
            .values(
                "id",
                "title",
                "description",
                "location",
                "start_time",
                "end_time",
                "event_status",
                "visibility",
            )[:limit]
        )
        return [
            {
                **event,
                "id": str(event["id"]),
                "start_time": event["start_time"].isoformat(),
                "end_time": event["end_time"].isoformat(),
            }
            for event in events
        ]

    def read_connected_external_calendar_summaries(
        self, family: FamilyGroup, *, limit: int = 25
