      : `/api/family-agent/proposals/${id}/${verb}/`;

    button.disabled = true;
    setStatus(verb === 'approve' ? 'Approving...' : 'Rejecting...');
    try {
      await apiRequest(path, { method: 'POST', json: {} });
      await loadMessages();
      setStatus('');
    } catch (error) {
      button.disabled = false;
      setStatus(error.message || 'Could not update the suggestion.');
    }
  }

  function renderEmptyState() {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    const empty = document.createElement('p');
    empty.className = 'clancy-assistant-empty';
    empty.textContent = `Ask ${helperName} for quick help, or open the full conversation when you need more room.`;
    messages.appendChild(empty);

    if (defaultPrompt.trim()) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'clancy-assistant-prompt-card';
      button.dataset.clancySuggestionPrompt = defaultPrompt;

      const label = document.createElement('span');
      label.className = 'clancy-assistant-prompt-card-label';
      label.textContent = 'Suggested prompt';

      const prompt = document.createElement('span');
      prompt.className = 'clancy-assistant-prompt-card-text';
      prompt.textContent = defaultPrompt;

      button.append(label, prompt);
      messages.appendChild(button);
    }
  }

  function renderMessages(items) {
    if (!messages) {
      return;
    }
    messages.replaceChildren();
    if (!items.length) {
      renderEmptyState();
      return;
    }
    items.slice(-8).forEach((message) => appendMessage(message));
