        ]

    def read_trip_summaries(
        self, family: FamilyGroup, *, user: User, limit: int = 10
    ) -> list[dict[str, Any]]:
        trips = (
            Trip.objects.filter(family_groups=family)
            .distinct()
            .order_by("-start_date")[:limit]
        )
        return [
            {
                "id": str(trip.id),
                "name": trip.name,
                "location": trip.location,
                "date_status": trip.date_status,
                "start_date": trip.start_date.isoformat() if trip.start_date else None,
